var inputJson = $input.first().json;

var data = inputJson;

if (inputJson.body !== undefined) {
  var rawBody = inputJson.body;
  if (typeof rawBody === 'string') {
    rawBody = rawBody.replace(/^=+/, '').trim();
    try {
      data = JSON.parse(rawBody);
    } catch(e) {
      data = inputJson;
    }
  } else if (typeof rawBody === 'object') {
    data = rawBody;
  }
}

return [{ json: data }];

const input = $input.first().json;
let code = input.codeconcat || input.code || "";

if ((!code || code.trim() === "" || code.includes("// no code")) && Array.isArray(input.files)) {
  code = input.files.map(f => `// FILE: ${f.path || "unknown"}\n${f.content || ""}`).join("\n\n");
}

if (!code || code.trim() === "") {
  return [{ json: { error: "Champ code manquant", valid: false } }];
}

return [{ json: { ...input, code, valid: true } }];

const input = $input.first().json;

// Limite 50KB
let code = input.code || input.codeconcat || "";
if (code.length > 50000) code = code.substring(0, 50000);

if (!code || code.trim() === "") {
  return [{ json: { error: "Code manquant", valid: false } }];
}

const taskid   = input.task_id || input.taskid || "unknown";
const language = input.language || "javascript";
const critical = [];
const warnings = [];

// ── A10 SSRF ────────────────────────────────────────────────────────────────
const hasHttpWithInput = /fetch\s*\(\s*req\.(body|params|query)/i.test(code) ||
  /axios\.\w+\s*\(\s*req\.(body|params|query)/i.test(code) ||
  /url\s*[:=]\s*req\.(body|params|query)/i.test(code);
if (hasHttpWithInput) critical.push({
  rule: "SSRF-001", severity: "high", owasp: "A10:2021",
  description: "SSRF : requête HTTP construite depuis une entrée utilisateur",
  file: "server.js",
  impact: "Accès à des ressources internes (metadata cloud, services internes)",
  fix: "Valider et whitelister les URLs avant tout appel HTTP externe"
});

// ── A03 Prototype Pollution ─────────────────────────────────────────────────
const hasProto = /__proto__\s*=/.test(code) ||
  /\[[\'\"]__proto__[\'\"]\]\s*=/.test(code) ||
  /Object\.assign\s*\(\s*\{\}\s*,\s*req\.(body|params|query)/i.test(code);
if (hasProto) critical.push({
  rule: "PROTO-001", severity: "high", owasp: "A03:2021",
  description: "Prototype Pollution : modification de __proto__ possible",
  file: "server.js",
  impact: "Corruption de l objet global JavaScript",
  fix: "Utiliser Object.create(null) ou valider les cles avant merge"
});

// ── A01 Path Traversal ──────────────────────────────────────────────────────
// Vérification fichier par fichier — évite les faux positifs cross-fichiers
// (ex: readFileSync dans db.js avec __dirname ≠ req.params dans server.js)
const hasFileOp = /readFile|writeFile|createReadStream|unlink/.test(code);
const hasUserInput = /req\.(body|params|query)/.test(code);
// Exclure les opérations sur chemins serveur constants (non contrôlables par l'utilisateur)
const hasSafeFileOp = /(?:readFile|writeFile|createReadStream)[A-Za-z]*\s*\([^)]*(?:__dirname|schemaPath|DB_PATH|path\.join\s*\(\s*__dirname)/.test(code);
// Détecter si l'entrée utilisateur est directement dans l'opération fichier
const hasUserInputInFileOp = /(?:readFile|writeFile|createReadStream|unlink)[A-Za-z]*\s*\([^)]*req\.(?:body|params|query)/.test(code);
if (hasFileOp && hasUserInput && !hasSafeFileOp && (hasUserInputInFileOp || !hasSafeFileOp)) {
  // Ne déclencher que si l'entrée utilisateur est réellement dans l'opération fichier
  if (hasUserInputInFileOp) critical.push({
    rule: "PATH-001", severity: "high", owasp: "A01:2021",
    description: "Path Traversal potentiel : operation fichier avec entree utilisateur",
    file: "server.js",
    impact: "Lecture ou ecriture de fichiers arbitraires sur le serveur",
    fix: "Valider et normaliser le chemin : path.basename(req.params.file)"
  });
}

// ── A08 Deserialisation non securisee ───────────────────────────────────────
const hasDeser = /node-serialize/.test(code) ||
  /unserialize\s*\(/.test(code) ||
  /yaml\.load\s*\(/.test(code);
if (hasDeser) critical.push({
  rule: "DESER-001", severity: "high", owasp: "A08:2021",
  description: "Deserialisation non securisee detectee",
  file: "?",
  impact: "Execution de code arbitraire lors de la deserialisation",
  fix: "Utiliser yaml.safeLoad() ou JSON.parse() avec validation"
});

// ── A01 Open Redirect ───────────────────────────────────────────────────────
const hasRedirect = /res\.redirect\s*\(/.test(code) && hasUserInput;
if (hasRedirect) critical.push({
  rule: "REDIR-001", severity: "high", owasp: "A01:2021",
  description: "Open Redirect potentiel : redirection vers URL utilisateur",
  file: "server.js",
  impact: "Phishing, vol de tokens via redirection malveillante",
  fix: "Whitelister les URLs de redirection autorisees"
});

// ── A02 Cryptographie faible ────────────────────────────────────────────────
const hasWeakCrypto = /createHash\s*\(\s*[\'\"`]md5[\'\"`]/i.test(code) ||
  /createHash\s*\(\s*[\'\"`]sha1[\'\"`]/i.test(code) ||
  /createCipher\s*\(\s*[\'\"`]des/i.test(code);
if (hasWeakCrypto) critical.push({
  rule: "CRYPTO-001", severity: "high", owasp: "A02:2021",
  description: "Algorithme cryptographique obsolete (MD5/SHA1/DES)",
  file: "?",
  impact: "Hachages cassables en quelques secondes",
  fix: "Utiliser bcrypt pour mots de passe, SHA-256+ pour les hachages"
});

// ── A02 Math.random pour valeurs securisees ─────────────────────────────────
const hasMathRandom = /Math\.random\s*\(\)/.test(code) &&
  /(token|secret|session|password|key|auth|csrf|nonce)/i.test(code);
if (hasMathRandom) critical.push({
  rule: "RAND-001", severity: "high", owasp: "A02:2021",
  description: "Math.random() utilise pour valeur cryptographique",
  file: "?",
  impact: "Valeurs predictibles — tokens devinables",
  fix: "Utiliser crypto.randomBytes(32).toString('hex')"
});

// ── A03 Command Injection ───────────────────────────────────────────────────
const hasCmdInjection = /execSync\s*\(/.test(code) && hasUserInput;
if (hasCmdInjection) critical.push({
  rule: "CMD-001", severity: "high", owasp: "A03:2021",
  description: "Command Injection potentiel : execSync avec entree utilisateur",
  file: "server.js",
  impact: "Execution de commandes systeme arbitraires",
  fix: "Ne jamais passer des donnees utilisateur a execSync ou spawn"
});

// ── Avertissements ───────────────────────────────────────────────────────────
if (/jwt\.sign\s*\(/.test(code) && !/expiresIn/.test(code))
  warnings.push({ rule: "JWT-001", severity: "medium",
    description: "JWT signe sans expiresIn — tokens sans expiration",
    fix: "jwt.sign(payload, secret, { expiresIn: '24h' })" });

if (/cors\(\)/i.test(code) && !/origin\s*:/i.test(code))
  warnings.push({ rule: "CORS-001", severity: "medium",
    description: "CORS avec wildcard — toutes origines autorisees",
    fix: "cors({ origin: ['https://votre-domaine.com'] })" });

if (/express\(\)/i.test(code) && !/helmet/i.test(code))
  warnings.push({ rule: "HDR-001", severity: "medium",
    description: "Helmet absent — headers de securite HTTP manquants",
    fix: "app.use(require('helmet')())" });

if (/http:\/\/(?!localhost|127\.0\.0\.1)/i.test(code))
  warnings.push({ rule: "TLS-001", severity: "medium",
    description: "URL HTTP non securisee detectee",
    fix: "Remplacer http:// par https:// pour les appels externes" });

const consoleSensitive = (code.match(/console\.(log|info)\s*\([^)]*(?:password|token|secret|key)/gi) || []).length;
if (consoleSensitive > 0)
  warnings.push({ rule: "LOG-001", severity: "medium",
    description: consoleSensitive + " console.log avec donnees potentiellement sensibles",
    fix: "Masquer ou supprimer les logs contenant des donnees sensibles" });

// -- A03 Injection SQL (concatenation / interpolation dans une requete) --
// SQLI-001 (V5.4) : ne flague que si une ENTREE UTILISATEUR (req.query/body/params) est
// concatenee/interpolee dans le SQL. La concatenation de valeurs whitelistees (noms de
// table, colonne de tri validee) n'est PAS une injection -> plus de faux positif.
var _sqlInterp = /`[^`]*\b(?:SELECT|INSERT|UPDATE|DELETE|WHERE|FROM)\b[^`]*\$\{[^}]*\breq\.(?:query|body|params)\b/i.test(code);
var _sqlConcat = /['"][^'"]*\b(?:SELECT|INSERT|UPDATE|DELETE|WHERE|FROM)\b[^'"]*['"]\s*\+[^;\n]*\breq\.(?:query|body|params)\b/i.test(code);
if (_sqlInterp || _sqlConcat) critical.push({
  rule: "SQLI-001", severity: "high", owasp: "A03:2021",
  description: "Injection SQL : requete construite par concatenation ou interpolation d entree",
  file: "server.js",
  impact: "Lecture, modification ou suppression de donnees arbitraires",
  fix: "Utiliser des requetes parametrees (db.prepare avec des ?)"
});

// -- A03 Execution de code dynamique --
if (/\beval\s*\(/.test(code) || /new\s+Function\s*\(/.test(code)) critical.push({
  rule: "EVAL-001", severity: "high", owasp: "A03:2021",
  description: "Execution de code dynamique (eval / new Function)",
  file: "?",
  impact: "Execution de code arbitraire",
  fix: "Supprimer eval / new Function ; utiliser des alternatives sures"
});

// -- A03 XSS reflechi (entree utilisateur renvoyee sans echappement) --
if (/res\.(send|write|end)\s*\([^)]*req\.(body|params|query)/i.test(code)) critical.push({
  rule: "XSS-001", severity: "high", owasp: "A03:2021",
  description: "XSS reflechi : entree utilisateur renvoyee sans echappement",
  file: "server.js",
  impact: "Execution de script dans le navigateur de la victime",
  fix: "Utiliser res.json, echapper la sortie, activer une CSP"
});

// -- A02 Secret JWT code en dur --
if (/jwt\.sign\s*\([^;]{0,200}?,\s*["'][A-Za-z0-9_\-]{6,}["']\s*[,)]/.test(code)) warnings.push({
  rule: "JWT-002", severity: "medium", owasp: "A02:2021",
  description: "Secret JWT potentiellement code en dur dans jwt.sign",
  fix: "Charger le secret depuis process.env"
});

// ── Scores et verdict ────────────────────────────────────────────────────────
const secScore  = Math.max(0, 100 - (critical.length * 25) - (warnings.length * 5));
const qualScore = warnings.length === 0 ? 100 : Math.max(40, 100 - (warnings.length * 12));
const globalScore = Math.round((secScore * 0.75) + (qualScore * 0.25));

const status = critical.length > 0 ? "FAIL"
             : warnings.length > 0  ? "WARN"
             : "PASS";

return [{
  json: {
    agent: "Agent SAST",
    _version: "5.4",
    task_id: taskid, status,
    global_score: globalScore,
    approved_for_pipeline: status !== "FAIL",
    language,
    critical_issues: critical,
    warnings,
    recommendations: critical.length > 0
      ? ["Corriger immediatement les vulnerabilites SAST avant tout deploiement"]
      : warnings.length > 0
        ? ["Resoudre les avertissements avant la mise en production"]
        : ["Code conforme aux standards SAST OWASP"],
    dimensions: {
      security: { score: secScore },
      quality:  { score: qualScore }
    },
    summary: critical.length > 0
      ? critical.length + " vulnerabilite(s) critique(s) OWASP detectee(s)"
      : warnings.length > 0
        ? warnings.length + " avertissement(s) de securite"
        : "Aucune vulnerabilite SAST detectee",
    timestamp: new Date().toISOString()
  }
}];

const det = $('SAST Analysis').first().json;
let sem = {};
try { sem = $input.first().json; } catch(e) {}
const semOk = !!(sem && sem.engine === 'semgrep' && Array.isArray(sem.critical_issues));

function _key(i){ return (i.rule || '') + '|' + (i.file || '') + '|' + String(i.description || '').slice(0, 50); }
let critical = Array.isArray(det.critical_issues) ? det.critical_issues.slice() : [];
let warnings = Array.isArray(det.warnings) ? det.warnings.slice() : [];
const seen = {};
critical.concat(warnings).forEach(function(i){ seen[_key(i)] = true; });

// Union : Semgrep vient EN COMPLEMENT, il n enleve jamais un finding deterministe.
if (semOk) {
  (sem.critical_issues || []).forEach(function(i){ i.engine = 'semgrep'; var k = _key(i); if (!seen[k]) { critical.push(i); seen[k] = true; } });
  (sem.warnings || []).forEach(function(i){ i.engine = 'semgrep'; var k = _key(i); if (!seen[k]) { warnings.push(i); seen[k] = true; } });
}

// Score = min des deux moteurs (Semgrep ne peut jamais RELEVER le score).
const detScore = (det.global_score != null) ? det.global_score : 100;
const semScore = (semOk && sem.global_score != null) ? sem.global_score : 100;
const mergedScore = Math.max(0, 100 - critical.length * 25 - warnings.length * 5);
const globalScore = Math.min(detScore, semScore, mergedScore);

const status = critical.length > 0 ? 'FAIL' : (warnings.length > 0 ? 'WARN' : 'PASS');

return [{ json: {
  agent: 'Agent SAST',
  _version: '5.4',
  task_id: det.task_id || 'unknown',
  status: status,
  global_score: globalScore,
  approved_for_pipeline: status !== 'FAIL',
  language: det.language || 'javascript',
  critical_issues: critical,
  warnings: warnings,
  engines: semOk ? ['deterministic', 'semgrep'] : ['deterministic'],
  semgrep_available: semOk,
  recommendations: det.recommendations || (critical.length > 0 ? ['Corriger les vulnerabilites avant deploiement'] : ['Code conforme SAST']),
  dimensions: { security: { score: globalScore }, quality: (det.dimensions && det.dimensions.quality) || { score: 100 } },
  summary: (critical.length > 0 ? (critical.length + ' vulnerabilite(s) critique(s) OWASP') : (warnings.length > 0 ? (warnings.length + ' avertissement(s)') : 'Aucune vulnerabilite SAST detectee')) + (semOk ? ' [deterministe + semgrep]' : ' [deterministe seul, semgrep indisponible]'),
  timestamp: new Date().toISOString()
}}];
